//! Upstream-generated splitter cases; regeneration is recorded in reports/ui-tl-blocks-1.md.

use t3_ui::screens::thread::blocks::flatten::{MessageFlattener, split_markdown_blocks};

#[test]
fn appended_deltas_do_not_scan_the_settled_prefix() {
    fn measure(fences: usize, legacy: bool) -> (usize, usize) {
        let mut source = "```rs\nlet settled = 1;\n```\n\n".repeat(fences);
        source.push_str("```rs\n");
        let mut flattener = MessageFlattener::new("work-proof");
        if legacy {
            flattener.update(&source);
        } else {
            flattener.ingest("work-proof", &source);
        }
        let before = flattener.work();
        for _ in 0..128 {
            source.push_str("x\n");
            if legacy {
                flattener.update(&source);
            } else {
                flattener.ingest("work-proof", &source);
            }
        }
        let after = flattener.work();
        (
            after.byte_work() - before.byte_work(),
            after.visited_rows - before.visited_rows,
        )
    }
    let legacy_small = measure(4, true);
    let legacy_large = measure(512, true);
    assert!(
        legacy_large.0 > legacy_small.0 * 8,
        "the full-source control must exhibit the reviewed defect"
    );
    let small = measure(4, false);
    let large = measure(512, false);
    eprintln!(
        "128 deltas: legacy 4/512 settled fences = {legacy_small:?}/{legacy_large:?}; append 4/512 = {small:?}/{large:?}"
    );
    assert!(
        large.0 <= small.0 + 4096,
        "128 deltas scanned/copied {small:?} with 4 settled fences versus {large:?} with 512"
    );
    assert!(
        large.1 <= small.1 + 16,
        "settled row visits grew: {small:?} versus {large:?}"
    );
}

#[test]
fn upstream_splitter_fixtures() {
    for &(source, expected) in SPLITTER_FIXTURES {
        assert_eq!(
            split_markdown_blocks(source),
            expected.map(<[_]>::to_vec),
            "{source:?}"
        );
    }
}

#[test]
fn borrowed_projection_updates_preserve_rows_and_reset_edits() {
    use std::rc::Rc;
    let mut flattener = MessageFlattener::new("message");
    let prefix = "```rs\nsettled\n```\n\n";
    let first = flattener.ingest("message", &format!("{prefix}tail"));
    let settled = first.document.block(1).expect("settled code");
    let next = flattener.ingest("message", &format!("{prefix}tail more"));
    assert!(Rc::ptr_eq(
        &settled,
        &next.document.block(1).expect("retained code")
    ));
    assert!(next.changed_from > settled.id.index);
    assert!(next.rows.iter().all(|row| row.text.is_some()));
    let edited = flattener.ingest("message", &format!("{prefix}edited tail"));
    assert_eq!(edited.changed_from, 0);
    assert!(!Rc::ptr_eq(
        &settled,
        &edited.document.block(1).expect("reset code")
    ));
    let shorter = flattener.ingest("message", "short");
    assert_eq!(
        shorter.document.source_range(0..5).as_deref(),
        Some("short")
    );
    assert_eq!(shorter.changed_from, 0);
    let other = flattener.ingest("other", "next");
    assert!(other.rows.iter().all(|row| row.id.message_id == "other"));
}

#[test]
fn document_context_is_gathered_incrementally_and_resolved_once() {
    let mut flattener = MessageFlattener::new("context");
    let mut source = "[ref]\n\n[ref]: /target\n\n".to_owned();
    let initial = flattener.ingest("context", &source);
    let definition = initial
        .document
        .definition("ref", false)
        .expect("published definition");
    assert_eq!(definition.node.data["url"], "/target");
    let version = initial.context_version;
    let before = flattener.work();
    for _ in 0..128 {
        source.push_str("x");
        flattener.ingest("context", &source);
    }
    let after = flattener.work();
    assert!(after.parsed_bytes - before.parsed_bytes < 20_000);
    let complete = flattener.finish().expect("finish open tail");
    assert!(std::rc::Rc::ptr_eq(
        &definition,
        &complete
            .document
            .definition("ref", false)
            .expect("retained definition")
    ));
    assert_eq!(complete.context_version, version);
    assert_eq!(
        complete.document.source_range(0..source.len()).as_deref(),
        Some(source.as_str())
    );
    let done = flattener.work();
    assert!(flattener.finish().is_none());
    assert_eq!(flattener.work(), done);
}

